+                                            axis("topN", List.of(2, 3))),
+                                    "MIN_VARIANCE",
+                                    strategy(axis("window", List.of(60, 120, 250, 500)))));
+
+            // 3 * 2 + 4 — 축 개수가 전략마다 달라도 같은 절차다.
+            assertThat(space.combinationCount()).isEqualTo(10L);
+        }
